{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C11"],
      "claim": "Mithramycin, a large polyhydroxylated glycoside, showed a peak CSF:plasma ratio of only 0.12 in monkeys and little brain distribution, directly demonstrating poor CNS access for a polar glycoside.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "SC-4453, a cardiac glycoside, had the lowest steady-state tissue concentration in the brain of guinea pigs, indicating a functional blood-brain barrier to this glycoside.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Orientin, a highly polar glycoside, showed low brain levels after intravenous administration in rats, attributed to difficulty crossing the BBB because of high polarity.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Epimedin B, a glycosylated flavonol, was the least concentrated compound in rat brain in a tissue distribution study, demonstrating poor blood-brain barrier passage.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Erythromycin, a large polar macrolide, achieved CSF concentrations of only 0.1-2.5 µg/mL versus serum levels of 8-12 µg/mL in adults with meningitis, indicating inadequate CNS penetration after systemic administration.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a large, highly polar, ionizable anthracycline-like glycoside. Direct experimental evidence from multiple related glycosides and polar natural products consistently shows poor brain/CSF penetration after systemic administration, so meaningful CNS access is unlikely.",
  "evidence_gaps": [
    "No direct brain or CSF measurement for the exact query molecule.",
    "Exact efflux transporter substrate status is not experimentally defined.",
    "No human pharmacokinetic data for this specific scaffold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

